import { router, publicProcedure } from '../trpc';
import { z } from 'zod';

export const mockPosts = Array.from({ length: 15 }).map((_, i) => ({
  id: i,
  title: `Post ${i}`,
}));

export const postsRouter = router({
  list: publicProcedure
    .input(
      z.object({
        limit: z.number().min(1).max(50),
        cursor: z.number().optional(),
      })
    )
    .query(({ input }) => {
      const limit = input.limit;
      const cursor = input.cursor ?? 0;

      const items = mockPosts.slice(cursor, cursor + limit);
      const nextCursor = cursor + limit < mockPosts.length ? cursor + limit : null;

      return {
        items,
        nextCursor,
      };
    }),
});

'use client';

import { trpc } from '../../trpc/client';
import React from 'react';

export function PostList() {
  const [data] = trpc.posts.list.useSuspenseInfiniteQuery(
    {},
    {
      getNextPageParam: (lastPage) => lastPage.nextCursor,
      initialCursor: 0,
    }
  );

  return (
    <div>
      <h2>Posts</h2>
      <ul>
        {data.pages.map((page) =>
          page.items.map((post) => (
            <li key={post.id}>{post.title}</li>
          ))
        )}
      </ul>
      <button
        disabled={!data.hasNextPage || data.isFetchingNextPage}
        onClick={() => data.fetchNextPage()}
      >
        Load More
      </button>
    </div>
  );
}

